const readline = require('readline');

function isVowel(c) {
    return c === 'A' || c === 'E' || c === 'O' || c === 'U' || c === 'Y' || c === 'I';
}

const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});

rl.on('line', (line) => {
    let str = ' ' + line + ' ';
    let jumpSize = 1;
    let pos = 0;
    let next;

    do {
        next = pos + 1;
        while (next < str.length && str[next] !== ' ' && !isVowel(str[next])) {
            next++;
        }
        jumpSize = Math.max(jumpSize, next - pos);
        pos = next;
    } while (pos < str.length && str[pos] !== ' ');

    console.log(jumpSize);
    rl.close();
});

const fs = require('fs');

function isVowel(c) {
    return c === 'A' || c === 'E' || c === 'O' || c === 'U' || c === 'Y' || c === 'I';
}

const input = fs.readFileSync(0, 'utf-8').trim();
const str = ' ' + input + ' ';
let jumpSize = 1;
let pos = 0;
let next;

do {
    next = pos + 1;
    while (str[next] !== ' ' && !isVowel(str[next])) {
        next++;
    }
    jumpSize = Math.max(jumpSize, next - pos);
    pos = next;
} while (str[pos] !== ' ');

console.log(jumpSize);

